function wcIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.page}"/></svg>`;}
const toolsRegistry=[];
function tool(label,icon,action,large=false){const b=document.createElement('button');b.type='button';b.className=large?'tool large':'tool';b.innerHTML=large?`<span class="symbol">${wcIcon(icon)}</span><span>${label}</span>`:wcIcon(icon)+`<span>${label}</span>`;b.title=label;b.setAttribute('aria-label',label);b.onmousedown=e=>e.preventDefault();b.onclick=()=>{if(readOnly&&!['view','help','file','review'].includes(activeTab)){toast('Dokumen dalam mode baca. Aktifkan penyuntingan untuk mengubahnya.');return;}action();};if(!toolsRegistry.some(t=>t.label===label))toolsRegistry.push({label,icon,action,tab:activeTab});return b;}
function small(label,html,action,cmd){if(!toolsRegistry.some(t=>t.label===label))toolsRegistry.push({label,icon:'text',action,tab:activeTab});const b=button(label,action,{icon:html});if(cmd)b.dataset.cmd=cmd;return b;}
function g(label,...items){group(label,items);}
function stackTools(...items){return stack(...items);}
function formSelect(items,fn,label,value){const el=select(items,fn,label);if(value!==undefined)el.value=value;return el;}
let readOnly=false,tracking=false,selectedImage=null,formatBrush=null,paginationTimer,paginating=false;
current.appearance=WC.appearance(current.appearance);
const originalLoad=loadDoc,originalChanged=changed,originalTravel=travelHistory,originalApplyLayout=applyLayout;
function cleanHTML(){const clone=editor.cloneNode(true);clone.querySelectorAll('.wc-running,[data-bookmark]').forEach(n=>n.remove());clone.querySelectorAll('.selected-image').forEach(n=>n.classList.remove('selected-image'));return clone.innerHTML;}
persist=function(){clearTimeout(saveTimer);current.html=cleanHTML();current.appearance=WC.appearance(current.appearance);current.title=$('documentTitle').value.trim()||'Dokumen tanpa judul';current.updated=Date.now();try{localStorage.setItem(STORAGE,JSON.stringify({docs,current:current.id}));storageFailed=false;$('savedState').textContent='Tersimpan di perangkat';}catch{storageFailed=true;$('savedState').textContent='Penyimpanan penuh — unduh cadangan';}$('breadcrumb').textContent=current.title;renderDocuments();};
loadDoc=function(){readOnly=false;tracking=false;editor.contentEditable='true';document.querySelector('.mode-label').innerHTML='<span></span> Mode menyunting';editor.querySelectorAll('.wc-running').forEach(n=>n.remove());originalLoad();current.appearance=WC.appearance(current.appearance);applyAppearance();paginate();};
changed=function(){originalChanged();schedulePagination();};
travelHistory=function(delta){originalTravel(delta);schedulePagination();};
applyLayout=function(){originalApplyLayout();schedulePagination();};
function schedulePagination(){if(paginating)return;clearTimeout(paginationTimer);paginationTimer=setTimeout(paginate,220);}
function saveBookmark(){let r=null;const sel=getSelection();if(sel.rangeCount&&editor.contains(sel.anchorNode)&&editor.contains(sel.focusNode))r=sel.getRangeAt(0).cloneRange();else if(savedRange&&editor.contains(savedRange.startContainer)&&editor.contains(savedRange.endContainer))r=savedRange.cloneRange();if(!r)return null;const start=document.createElement('span'),end=document.createElement('span');start.dataset.bookmark='start';end.dataset.bookmark='end';start.style.display=end.style.display='none';const tail=r.cloneRange();tail.collapse(false);tail.insertNode(end);r.collapse(true);r.insertNode(start);return{start,end};}
function restoreBookmark(mark){if(!mark)return;if(editor.contains(mark.start)&&editor.contains(mark.end)){const r=document.createRange();r.setStartAfter(mark.start);r.setEndBefore(mark.end);mark.start.remove();mark.end.remove();savedRange=r;const sel=getSelection();sel.removeAllRanges();sel.addRange(r);}else{mark.start.remove();mark.end.remove();savedRange=null;}}
function newSheet(){const sheet=document.createElement('div');sheet.className='wc-sheet';editor.append(sheet);return sheet;}
function sheetBlocks(){const result=[];for(const n of [...editor.childNodes]){if(n.nodeType===1&&n.classList.contains('wc-sheet')){for(const child of [...n.childNodes])if(!(child.nodeType===1&&child.classList.contains('wc-running')))result.push(child);}else if(!(n.nodeType===1&&n.classList.contains('wc-running')))result.push(n);}return result;}
function splitTextBlock(block,sheet,height){const walker=document.createTreeWalker(block,NodeFilter.SHOW_TEXT);const nodes=[];let n,total=0;while((n=walker.nextNode())){nodes.push({node:n,start:total,end:total+n.length});total+=n.length;}if(total<30)return null;function point(offset){const entry=nodes.find(x=>x.end>=offset)||nodes.at(-1);return[entry.node,Math.max(0,Math.min(entry.node.length,offset-entry.start))];}let lo=1,hi=total-1,best=0;for(let step=0;step<16&&lo<=hi;step++){const mid=Math.floor((lo+hi)/2),[node,offset]=point(mid),range=document.createRange();range.selectNodeContents(block);range.setEnd(node,offset);const test=block.cloneNode(false);test.append(range.cloneContents());block.style.display='none';sheet.append(test);const fits=sheet.scrollHeight<=height+1;test.remove();block.style.display='';if(fits){best=mid;lo=mid+1;}else hi=mid-1;}if(best<2||best>=total-1)return null;const content=block.textContent;const space=content.lastIndexOf(' ',best);if(space>best*.7)best=space+1;const [node,offset]=point(best);const range=document.createRange();range.selectNodeContents(block);range.setStart(node,offset);const tail=block.cloneNode(false);tail.removeAttribute('id');tail.append(range.extractContents());return tail;}
function splitTable(table,sheet,height){if(table.rows.length<2)return null;const tail=table.cloneNode(false),body=document.createElement('tbody');tail.append(body);while(table.rows.length>(table.rows[0]?.querySelector('th')?2:1)&&sheet.scrollHeight>height+1){body.prepend(table.rows[table.rows.length-1]);}if(!body.children.length)return null;const first=table.rows[0];if(first&&first.querySelector('th'))body.prepend(first.cloneNode(true));return tail;}
function paginate(){if(paginating)return;paginating=true;const mark=saveBookmark();const blocks=sheetBlocks();editor.replaceChildren();let sheet=newSheet();const height=parseFloat(getComputedStyle(editor).getPropertyValue('--paper-height'))||1123;const padding=parseFloat(getComputedStyle(editor).getPropertyValue('--paper-padding'))||76;const columns=WC.appearance(current.appearance).columns;let work=[...blocks],guard=0;
 while(work.length&&guard++<2000){let block=work.shift();if(block.nodeType===3){if(!block.textContent.trim())continue;const p=document.createElement('p');p.append(block);block=p;}if(block.nodeType!==1)continue;if(block.classList.contains('page-break')){sheet.append(block);sheet=newSheet();continue;}sheet.append(block);const overflow=sheet.scrollHeight>height+1;if(!overflow||columns>1||document.body.classList.contains('web-layout'))continue;
 if(sheet.children.length>1){block.remove();sheet=newSheet();sheet.append(block);}if(sheet.scrollHeight>height+1){let tail=null;if(block.tagName==='TABLE')tail=splitTable(block,sheet,height);else if(/^(P|H[1-6]|BLOCKQUOTE|DIV)$/.test(block.tagName)&&block.getBoundingClientRect().height>height-padding*2-10&&!block.querySelector('table,img'))tail=splitTextBlock(block,sheet,height);else if(['UL','OL'].includes(block.tagName)&&block.children.length>1){tail=block.cloneNode(false);const originalCount=block.children.length;while(block.children.length>1&&sheet.scrollHeight>height+1)tail.prepend(block.lastElementChild);if(tail.children.length&&block.tagName==='OL')tail.setAttribute('start',(+block.getAttribute('start')||1)+originalCount-tail.children.length);if(!tail.children.length)tail=null;}if(tail){work.unshift(tail);sheet=newSheet();}}
 }
 if(work.length){for(const block of work)sheet.append(block);}if(!editor.textContent&&!editor.querySelector('img,table')){const first=editor.querySelector('.wc-sheet');if(!first.children.length)first.innerHTML='<p><br></p>';}for(const s of editor.querySelectorAll('.wc-sheet'))if(!s.childNodes.length)s.innerHTML='<p><br></p>';applyAppearance();restoreBookmark(mark);paginating=false;updateStats();}
function applyAppearance(){editor.querySelectorAll('del[data-change]').forEach(n=>n.contentEditable='false');const a=current.appearance=WC.appearance(current.appearance);document.documentElement.style.setProperty('--wc-paper',a.pageColor);document.documentElement.style.setProperty('--wc-heading',a.theme==='formal'?'#222222':a.theme==='modern'?'#007c83':'#2f5496');editor.dataset.theme=a.theme;for(const [i,sheet] of [...editor.querySelectorAll('.wc-sheet')].entries()){sheet.classList.toggle('bordered',a.border);sheet.classList.toggle('two-columns',a.columns===2);sheet.classList.toggle('three-columns',a.columns===3);sheet.dataset.watermark=a.watermark;sheet.dataset.page=a.pageNumbers?String(i+1):'';sheet.querySelectorAll('.wc-running').forEach(n=>n.remove());for(const [position,text] of [['head',a.header],['foot',a.footer]])if(text){const running=document.createElement('div');running.className='wc-running '+position;running.contentEditable='false';running.textContent=text;sheet.prepend(running);}}}
updateStats=function(){const clone=editor.cloneNode(true);clone.querySelectorAll('.wc-running,del').forEach(n=>n.remove());const text=plainText(clone);const words=text.trim()?text.trim().split(/\s+/u).length:0;$('wordCount').textContent=words.toLocaleString('id-ID')+' kata';const sheets=[...editor.querySelectorAll('.wc-sheet')];let page=1;const node=getSelection().anchorNode;const el=node?.nodeType===1?node:node?.parentElement;const active=el?.closest('.wc-sheet');if(active)page=sheets.indexOf(active)+1;$('pageCount').textContent='Halaman '+Math.max(1,page)+' dari '+Math.max(1,sheets.length);$('pageHolder').style.height=(editor.offsetHeight*zoom/100)+'px';};
function mutate(fn){if(readOnly){toast('Aktifkan penyuntingan terlebih dahulu.');return;}restoreSelection();fn();rememberSelection();changed();}
function applyInline(style){mutate(()=>{const r=getSelection().getRangeAt(0);if(r.collapsed){const span=document.createElement('span');Object.assign(span.style,style);span.append(document.createTextNode('\u200b'));r.insertNode(span);r.selectNodeContents(span);r.collapse(false);getSelection().removeAllRanges();getSelection().addRange(r);}else{const span=document.createElement('span');Object.assign(span.style,style);span.append(r.extractContents());r.insertNode(span);r.selectNodeContents(span);getSelection().removeAllRanges();getSelection().addRange(r);}});}
function fontSize(pt){pt=Math.min(200,Math.max(5,Number(pt)||11));mutate(()=>{document.execCommand('fontSize',false,'7');editor.querySelectorAll('font[size="7"]').forEach(el=>{el.removeAttribute('size');el.style.fontSize=pt+'pt';});});}
function changeCase(mode){restoreSelection();const s=getSelection().toString();if(!s){toast('Pilih teks terlebih dahulu.');return;}const text=mode==='upper'?s.toLocaleUpperCase('id'):mode==='lower'?s.toLocaleLowerCase('id'):s.toLocaleLowerCase('id').replace(/(^|\s)(\p{L})/gu,(_,space,c)=>space+c.toLocaleUpperCase('id'));command('insertText',text);}
function changeCaseDialog(){showDialog('Ubah huruf','<label>Pilih perubahan<select name="mode"><option value="upper">HURUF BESAR</option><option value="lower">huruf kecil</option><option value="title">Huruf Awal Kapital</option></select></label>',d=>changeCase(d.get('mode')));}
function paragraphDialog(){showDialog('Paragraf','<div class="form-grid"><label>Spasi baris<select name="line"><option>1</option><option>1.15</option><option selected>1.5</option><option>2</option><option>2.5</option><option>3</option></select></label><label>Perataan<select name="align"><option value="left">Kiri</option><option value="center">Tengah</option><option value="right">Kanan</option><option value="justify">Kiri dan kanan</option></select></label><label>Sebelum (pt)<input name="before" type="number" min="0" max="120" value="0"></label><label>Sesudah (pt)<input name="after" type="number" min="0" max="120" value="8"></label><label>Inden kiri (cm)<input name="left" type="number" step="0.1" min="0" max="10" value="0"></label><label>Baris pertama (cm)<input name="first" type="number" step="0.1" min="0" max="5" value="0"></label></div>',d=>mutate(()=>{const b=currentBlock();let blocks=b?[b]:[...editor.querySelectorAll('.wc-sheet>p,.wc-sheet>h1,.wc-sheet>h2,.wc-sheet>h3,.wc-sheet>li')];for(const p of blocks)Object.assign(p.style,{lineHeight:d.get('line'),textAlign:d.get('align'),marginTop:d.get('before')+'pt',marginBottom:d.get('after')+'pt',marginLeft:d.get('left')+'cm',textIndent:d.get('first')+'cm'});}));}
function fontDialog(){showDialog('Font','<div class="form-grid"><label>Font<select name="font"><option>Calibri</option><option>Aptos</option><option>Arial</option><option>Times New Roman</option><option>Georgia</option><option>Verdana</option><option>Cambria</option><option>Courier New</option></select></label><label>Ukuran (pt)<input name="size" type="number" min="5" max="200" value="11"></label><label>Warna<input name="color" type="color" value="#000000"></label><label>Gaya<select name="style"><option value="normal">Normal</option><option value="italic">Miring</option></select></label></div><label class="check-label"><input name="bold" type="checkbox"> Tebal</label><div class="font-preview" id="fontPreview">WordCraft — Aa Bb Cc 123</div>',d=>{applyInline({fontFamily:d.get('font'),fontSize:d.get('size')+'pt',color:d.get('color'),fontStyle:d.get('style'),fontWeight:d.has('bold')?'700':'400'});});$('dialogForm').oninput=()=>{const d=new FormData($('dialogForm'));Object.assign($('fontPreview').style,{fontFamily:d.get('font'),fontSize:d.get('size')+'pt',color:d.get('color'),fontStyle:d.get('style'),fontWeight:d.has('bold')?'700':'400'});};}
function colorTool(label,cmd,color,letter){const el=document.createElement('label');el.className='color-tool';el.title=label;el.style.setProperty('--swatch',color);el.innerHTML=`<span>${letter}</span><input type="color" value="${color}" aria-label="${label}">`;el.querySelector('input').oninput=e=>{el.style.setProperty('--swatch',e.target.value);command(cmd,e.target.value);};return el;}
async function clipboard(action){restoreSelection();if(action==='paste'){try{const text=await navigator.clipboard.readText();command('insertText',text);}catch{toast('Gunakan Ctrl+V / ⌘+V untuk menempel dari clipboard.');}}else{const text=getSelection().toString();if(!text){toast('Pilih teks terlebih dahulu.');return;}try{await navigator.clipboard.writeText(text);if(action==='cut')command('delete');else toast('Teks disalin.');}catch{toast('Gunakan Ctrl+'+(action==='cut'?'X':'C')+' untuk clipboard browser.');}}}
function paintFormat(){restoreSelection();const n=getSelection().anchorNode;const el=n?.nodeType===1?n:n?.parentElement;if(!el||!editor.contains(el))return;const s=getComputedStyle(el);formatBrush={fontFamily:s.fontFamily,fontSize:s.fontSize,fontWeight:s.fontWeight,fontStyle:s.fontStyle,color:s.color};toast('Pilih teks tujuan untuk menerapkan format.');const apply=()=>{if(formatBrush&&getSelection().toString()){const style=formatBrush;formatBrush=null;applyInline(style);editor.removeEventListener('mouseup',apply);}};editor.addEventListener('mouseup',apply);}
function setAppearance(patch){current.appearance=WC.appearance({...current.appearance,...patch});applyAppearance();schedulePagination();persist();}
function themeDialog(){const a=current.appearance;showDialog('Desain dokumen',`<div class="form-grid"><label>Tema<select name="theme"><option value="office">Office — Calibri / biru</option><option value="modern">Modern — Arial / teal</option><option value="formal">Formal — Times New Roman / hitam</option></select></label><label>Warna kertas<select name="color"><option value="#ffffff">Putih</option><option value="#fffdf5">Krem</option><option value="#f2f7ff">Biru muda</option><option value="#f2f7f2">Hijau muda</option><option value="#f8f0f0">Merah muda</option></select></label></div><label class="check-label"><input name="border" type="checkbox"> Bingkai halaman</label>`,d=>setAppearance({theme:d.get('theme'),pageColor:d.get('color'),border:d.has('border')}));$('dialogForm').elements.theme.value=a.theme;$('dialogForm').elements.color.value=a.pageColor;$('dialogForm').elements.border.checked=a.border;}
function watermarkDialog(){showDialog('Watermark','<label>Teks watermark<input name="text" maxlength="60" placeholder="DRAFT / RAHASIA"></label><p>Kosongkan untuk menghapus. Watermark tampil pada kanvas dan saat cetak dengan grafik latar diaktifkan.</p>',d=>setAppearance({watermark:d.get('text')}));$('dialogForm').elements.text.value=current.appearance.watermark;}
function headerFooterDialog(){showDialog('Header & footer','<label>Header<input name="header" maxlength="150" placeholder="Nama organisasi / judul dokumen"></label><label>Footer<input name="footer" maxlength="150" placeholder="Keterangan dokumen"></label><label class="check-label"><input name="numbers" type="checkbox"> Nomor halaman</label><p>Diulang pada setiap halaman kanvas, cetak, dan ekspor DOCX. Tata letak cetak bergantung pada browser.</p>',d=>setAppearance({header:d.get('header'),footer:d.get('footer'),pageNumbers:d.has('numbers')}));$('dialogForm').elements.header.value=current.appearance.header;$('dialogForm').elements.footer.value=current.appearance.footer;$('dialogForm').elements.numbers.checked=current.appearance.pageNumbers;}
function columnsDialog(){showDialog('Kolom teks','<label>Jumlah kolom<select name="columns"><option value="1">Satu kolom</option><option value="2">Dua kolom</option><option value="3">Tiga kolom</option></select></label><p>Kolom berlaku untuk seluruh dokumen pada kanvas dan HTML. Penyebaran otomatis halaman dibatasi pada mode satu kolom.</p>',d=>setAppearance({columns:+d.get('columns')}));$('dialogForm').elements.columns.value=current.appearance.columns;}
function orientationDialog(){showDialog('Orientasi halaman','<label>Orientasi<select name="orientation"><option value="portrait">Potret</option><option value="landscape">Lanskap</option></select></label>',d=>{current.layout.orientation=d.get('orientation');applyLayout();persist();});$('dialogForm').elements.orientation.value=current.layout.orientation;}
function advancedTable(){showDialog('Sisipkan tabel','<div id="tableGrid" class="table-grid-picker"></div><p id="tableSize">Pilih ukuran tabel</p><div class="form-grid"><label>Baris<input type="number" name="rows" min="1" max="50" value="3" required></label><label>Kolom<input type="number" name="cols" min="1" max="12" value="3" required></label></div><label class="check-label"><input type="checkbox" name="header" checked> Kepala tabel</label>',d=>createTable(+d.get('rows'),+d.get('cols'),d.has('header')),'Sisipkan');for(let y=1;y<=8;y++)for(let x=1;x<=10;x++){const b=document.createElement('button');b.type='button';b.title=y+' × '+x;b.onmouseenter=()=>{[...$('tableGrid').children].forEach((c,i)=>c.classList.toggle('highlight',Math.floor(i/10)<y&&i%10<x));$('tableSize').textContent=x+' kolom × '+y+' baris';};b.onclick=()=>{$('dialog').close();createTable(y,x,true);};$('tableGrid').append(b);}}
function createTable(rows,cols,header){rows=Math.max(1,Math.min(50,rows));cols=Math.max(1,Math.min(12,cols));let html='<table><tbody>';for(let y=0;y<rows;y++){html+='<tr>';for(let x=0;x<cols;x++){const tag=y===0&&header?'th':'td';html+=`<${tag}>${tag==='th'?'Kolom '+(x+1):'<br>'}</${tag}>`;}html+='</tr>';}insertHTML(html+'</tbody></table><p><br></p>');}
function tableProperties(){showDialog('Properti tabel','<div class="form-grid"><label>Warna garis<input name="border" type="color" value="#7f9dbf"></label><label>Latar baris kepala<input name="fill" type="color" value="#d9e5f5"></label><label>Padding sel (px)<input type="number" name="padding" min="0" max="30" value="6"></label><label>Lebar tabel (%)<input type="number" name="width" min="10" max="100" value="100"></label></div><label class="check-label"><input type="checkbox" name="striped"> Baris berselang</label>',d=>mutate(()=>{const n=getSelection().anchorNode;const table=(n?.nodeType===1?n:n?.parentElement)?.closest('table');if(!table||!editor.contains(table))throw Error('Letakkan kursor di dalam tabel.');table.style.width=d.get('width')+'%';for(const [i,r] of [...table.rows].entries())for(const cell of r.cells){cell.style.border='1px solid '+d.get('border');cell.style.padding=d.get('padding')+'px';cell.style.backgroundColor=cell.tagName==='TH'?d.get('fill'):d.has('striped')&&i%2===0?'#f0f4fa':'transparent';}}));}
function mergeCells(){mutate(()=>{const s=getSelection(),n=s.anchorNode,cell=(n?.nodeType===1?n:n?.parentElement)?.closest('td,th');if(!cell||!editor.contains(cell))throw Error('Letakkan kursor pada sel kiri yang akan digabung.');const next=cell.nextElementSibling;if(!next)throw Error('Tidak ada sel di sebelah kanan.');cell.colSpan+=next.colSpan;cell.innerHTML+='<br>'+next.innerHTML;next.remove();});}
function splitCell(){mutate(()=>{const n=getSelection().anchorNode,cell=(n?.nodeType===1?n:n?.parentElement)?.closest('td,th');if(!cell||cell.colSpan<2){toast('Pilih sel yang sebelumnya digabung.');return;}const span=cell.colSpan;cell.colSpan=1;for(let i=1;i<span;i++){const td=document.createElement(cell.tagName);td.innerHTML='<br>';cell.after(td);}});}
function imageProperties(){if(!selectedImage||!editor.contains(selectedImage)){toast('Klik gambar terlebih dahulu.');return;}const img=selectedImage;showDialog('Format gambar',`<div class="form-grid"><label>Lebar (px)<input name="width" type="number" min="20" max="1200" value="${Math.round(img.getBoundingClientRect().width/(zoom/100))}"></label><label>Perataan<select name="align"><option value="left">Kiri</option><option value="center">Tengah</option><option value="right">Kanan</option></select></label></div><label>Teks alternatif<input name="alt" maxlength="200"></label><label class="check-label"><input name="border" type="checkbox"> Garis tepi</label>`,d=>mutate(()=>{img.style.width=d.get('width')+'px';img.style.height='auto';img.alt=d.get('alt');img.style.border=d.has('border')?'1px solid #777':'';if(img.parentElement)img.parentElement.style.textAlign=d.get('align');}));$('dialogForm').elements.alt.value=img.alt;}
function shapeDialog(){showDialog('Sisipkan bentuk / kotak teks','<label>Bentuk<select name="shape"><option value="box">Kotak teks</option><option value="round">Kotak sudut bulat</option><option value="pill">Oval</option><option value="callout">Kutipan</option></select></label><label>Teks<input name="text" value="Teks Anda" required></label><div class="form-grid"><label>Warna isi<input name="fill" type="color" value="#dae6f8"></label><label>Warna garis<input name="border" type="color" value="#4472c4"></label></div>',d=>insertHTML(`<div class="wc-shape" data-shape="${d.get('shape')}" style="border:2px solid ${d.get('border')};background-color:${d.get('fill')};padding:18px;text-align:center;border-radius:${d.get('shape')==='pill'?'50%':d.get('shape')==='round'?'14px':'0'}">${escapeHTML(d.get('text'))}</div><p><br></p>`),'Sisipkan');}
function equationDialog(){showDialog('Persamaan (Unicode)','<label>Persamaan<input name="equation" value="x = (−b ± √(b² − 4ac)) / 2a" required></label><p>Masukkan notasi Unicode. Ini bukan editor LaTeX atau mesin persamaan OMML Word.</p>',d=>insertHTML('<p style="text-align:center;font-family:Cambria Math,Georgia;font-size:16pt">'+escapeHTML(d.get('equation'))+'</p>'),'Sisipkan');}
function drawingDialog(){showDialog('Kanvas gambar','<div class="drawing-tools"><label>Warna<input id="penColor" type="color" value="#185abd"></label><label>Ketebalan<input id="penWidth" type="number" min="1" max="40" value="3"></label><button type="button" class="secondary" id="drawUndo">Urungkan</button><button type="button" class="secondary" id="drawClear">Hapus</button></div><canvas id="drawingBoard" class="drawing-board" width="1000" height="450"></canvas>',()=>{const c=$('drawingBoard');insertHTML('<p><img src="'+c.toDataURL('image/png')+'" alt="Gambar buatan di WordCraft" style="width:600px;max-width:100%"></p><p><br></p>');},'Sisipkan gambar');$('dialog').classList.add('wide');const canvas=$('drawingBoard'),ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,1000,450);let down=false;const history=[];const point=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*1000/r.width,(e.clientY-r.top)*450/r.height];};canvas.onpointerdown=e=>{history.push(ctx.getImageData(0,0,1000,450));if(history.length>15)history.shift();down=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));ctx.strokeStyle=$('penColor').value;ctx.lineWidth=+$('penWidth').value*2;ctx.lineCap=ctx.lineJoin='round';};canvas.onpointermove=e=>{if(!down)return;ctx.lineTo(...point(e));ctx.stroke();};canvas.onpointerup=()=>down=false;canvas.onpointercancel=()=>down=false;$('drawUndo').onclick=()=>{const last=history.pop();if(last)ctx.putImageData(last,0,0);};$('drawClear').onclick=()=>{history.push(ctx.getImageData(0,0,1000,450));ctx.fillStyle='#fff';ctx.fillRect(0,0,1000,450);};}
function tocHTML(){const heads=[...editor.querySelectorAll('h1,h2,h3')].filter(h=>!h.closest('.wc-toc'));if(!heads.length){toast('Terapkan gaya Judul 1–3 terlebih dahulu.');return null;}return '<div class="wc-toc" data-toc="1"><p><b>Daftar Isi</b></p>'+heads.map(h=>{if(!h.id)h.id='heading-'+uid();return '<p style="margin-left:'+((+h.tagName[1]-1)*15)+'px"><a href="#'+h.id+'">'+escapeHTML(h.textContent)+'</a></p>';}).join('')+'</div><p><br></p>';}
function insertTOC(){restoreSelection();const html=tocHTML();if(html)insertHTML(html);}
function updateTOC(){mutate(()=>{const html=tocHTML();if(!html)return;const old=editor.querySelector('.wc-toc');if(!old){toast('Belum ada daftar isi. Gunakan Sisipkan Daftar Isi.');return;}const temp=document.createElement('div');temp.innerHTML=html;old.replaceWith(temp.firstElementChild);});}
function footnoteDialog(){showDialog('Sisipkan catatan kaki','<label>Isi catatan<input name="text" maxlength="1000" required></label><p>Catatan dikumpulkan di bagian akhir dokumen. Catatan ini belum mengikuti pagination catatan kaki Word.</p>',d=>{const id='fn-'+uid(),number=editor.querySelectorAll('[data-footnote]').length+1;insertHTML('<sup data-footnote="'+id+'"><a href="#'+id+'">'+number+'</a></sup>');let notes=editor.querySelector('.wc-footnotes');if(!notes){notes=document.createElement('div');notes.className='wc-footnotes';(editor.querySelector('.wc-sheet:last-child')||editor).append(notes);}const p=document.createElement('p');p.id=id;p.textContent=number+'. '+d.get('text');notes.append(p);changed();},'Sisipkan');}
function captionDialog(){const count=editor.querySelectorAll('[data-caption]').length+1;showDialog('Sisipkan keterangan','<label>Label<select name="label"><option>Gambar</option><option>Tabel</option><option>Persamaan</option></select></label><label>Keterangan<input name="text" required maxlength="250"></label>',d=>insertHTML('<p data-caption="'+count+'" style="text-align:center;font-style:italic;font-size:10pt">'+escapeHTML(d.get('label'))+' '+count+' — '+escapeHTML(d.get('text'))+'</p>'),'Sisipkan');}
function citationDialog(){showDialog('Tambah sumber kutipan','<label>Penulis<input name="author" required maxlength="150"></label><div class="form-grid"><label>Tahun<input name="year" type="number" min="1000" max="2100" value="'+new Date().getFullYear()+'"></label><label>Kota / penerbit<input name="publisher" maxlength="150"></label></div><label>Judul sumber<input name="title" required maxlength="250"></label><p>Format kutipan sederhana: (Penulis, Tahun). Bukan pengelola sitasi APA/MLA lengkap.</p>',d=>{current.sources=Array.isArray(current.sources)?current.sources:[];current.sources.push({id:uid(),author:d.get('author'),year:d.get('year'),title:d.get('title'),publisher:d.get('publisher')});insertHTML(escapeHTML('('+d.get('author')+', '+d.get('year')+')'));persist();},'Sisipkan kutipan');}
function bibliography(){if(!current.sources?.length){toast('Tambahkan sumber kutipan terlebih dahulu.');return;}insertHTML('<h2>Daftar Pustaka</h2>'+current.sources.map(s=>'<p>'+escapeHTML(s.author)+'. ('+escapeHTML(s.year)+'). <i>'+escapeHTML(s.title)+'</i>. '+escapeHTML(s.publisher||'')+'.</p>').join(''));}
function csvFile(){const input=document.createElement('input');input.type='file';input.accept='.csv,.txt';input.onchange=async()=>{const f=input.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('CSV maksimal 2 MB.');current.mergeData=WC.parseCSV(await f.text());persist();toast(current.mergeData.rows.length+' penerima dimuat. Pilih Sisipkan Bidang.');renderRibbon('mailings');}catch(e){toast(e.message);}};input.click();}
function mergeFields(){const data=current.mergeData;if(!data?.headers?.length){toast('Pilih Penerima → buka CSV terlebih dahulu.');return;}showDialog('Sisipkan bidang gabung','<label>Nama bidang<select name="field">'+data.headers.map(h=>'<option>'+escapeHTML(h)+'</option>').join('')+'</select></label><p>Bidang akan diganti dengan data penerima saat pratinjau atau unduhan gabungan.</p>',d=>insertHTML('<span data-field="'+escapeHTML(d.get('field'))+'" style="background-color:#e7effa">{{'+escapeHTML(d.get('field'))+'}}</span>'),'Sisipkan');}
function standaloneHTML(html,title=current.title){const a=current.appearance;const box=document.createElement('div');box.innerHTML=html;const sheets=[...box.querySelectorAll('.wc-sheet')];for(const [i,sheet] of sheets.entries()){if(a.header){const head=document.createElement('div');head.className='wc-export-header';head.textContent=a.header;sheet.prepend(head);}if(a.footer||a.pageNumbers){const foot=document.createElement('div');foot.className='wc-export-footer';foot.textContent=a.footer+(a.pageNumbers?' — '+(i+1):'');sheet.append(foot);}}html=box.innerHTML;return '<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><title>'+escapeHTML(title)+'</title><style>body{font:11pt/1.35 Calibri,Arial,sans-serif;margin:30px auto;max-width:794px;color:#111}h1,h2,h3{color:#2f5496}table{width:100%;border-collapse:collapse}td,th{border:1px solid #888;padding:6px}img{max-width:100%;height:auto}.wc-sheet{box-sizing:border-box;position:relative;padding:40px;margin:0 0 25px;background:'+a.pageColor+';min-height:850px;break-after:page}.wc-sheet:last-child{break-after:auto}del{display:none}ins{text-decoration:none}.page-break{display:none}.wc-running{display:none}.wc-toc a{color:inherit;text-decoration:none}@media print{@page{size:'+current.layout.size+' '+current.layout.orientation+';margin:'+current.layout.margin+'mm}body{margin:0}.wc-sheet{margin:0;min-height:0;padding:0;box-shadow:none}.wc-export-header{top:-12mm;left:0}.wc-export-footer{bottom:-12mm;left:0}}</style></head><body>'+html+'</body></html>';}
exportHTML=function(){return standaloneHTML(sanitize(cleanHTML()));};
function mergedHTML(row){return WC.mergeHTML(cleanHTML(),row);}
function mergePreview(){const data=current.mergeData;if(!data?.rows?.length){toast('Muat data penerima CSV terlebih dahulu.');return;}showDialog('Pratinjau gabung surat','<label>Penerima<select id="mergeRecipient">'+data.rows.map((r,i)=>'<option value="'+i+'">'+(i+1)+'. '+escapeHTML(r[data.headers[0]])+'</option>').join('')+'</select></label><div id="mergePreview" class="merge-preview"></div>',null);$('dialog').classList.add('wide');const update=()=>{$('mergePreview').innerHTML=sanitize(mergedHTML(data.rows[+$('mergeRecipient').value]));$('mergePreview').querySelectorAll('.wc-sheet').forEach(s=>{s.style.cssText='padding:15px;min-height:0;width:auto;margin:0;box-shadow:none';});};$('mergeRecipient').onchange=update;update();}
async function downloadMerge(){const data=current.mergeData;if(!data?.rows?.length){toast('Muat data CSV terlebih dahulu.');return;}const entries={};for(let i=0;i<data.rows.length;i++)entries[String(i+1).padStart(3,'0')+'-'+filename()+'.html']=standaloneHTML(sanitize(mergedHTML(data.rows[i])),current.title+' — '+(i+1));const bytes=WordCraftOffice.zip(entries);download(bytes,filename()+'-gabung-surat.zip','application/zip');toast(data.rows.length+' surat HTML diunduh dalam ZIP.');}
function mergeToDocument(){const data=current.mergeData;if(!data?.rows?.length){toast('Muat data CSV terlebih dahulu.');return;}showDialog('Gabung ke dokumen baru','<label>Penerima<select name="index">'+data.rows.map((r,i)=>'<option value="'+i+'">'+(i+1)+'. '+escapeHTML(r[data.headers[0]])+'</option>').join('')+'</select></label>',d=>{const html=sanitize(mergedHTML(data.rows[+d.get('index')])),appearance={...current.appearance},layout={...current.layout},title=current.title+' — '+(Number(d.get('index'))+1);newDoc(html,title);current.appearance=appearance;current.layout=layout;applyLayout();applyAppearance();paginate();persist();},'Buat dokumen');}
function recipients(){const data=current.mergeData;if(!data?.rows?.length){csvFile();return;}showDialog('Daftar penerima','<p>'+data.rows.length+' penerima. Data disimpan hanya di perangkat ini.</p><div style="max-height:320px;overflow:auto"><table style="border-collapse:collapse;width:100%;font-size:11px"><thead><tr>'+data.headers.map(h=>'<th style="padding:8px;border:1px solid #ccc">'+escapeHTML(h)+'</th>').join('')+'</tr></thead><tbody>'+data.rows.slice(0,100).map(r=>'<tr>'+data.headers.map(h=>'<td style="padding:7px;border:1px solid #ddd">'+escapeHTML(r[h])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>Pratinjau dibatasi 100 baris pertama.</p>',null);$('dialog').classList.add('wide');}
function revisionHTML(fragment,tag,id){const box=document.createElement(tag);box.dataset.change=id;box.dataset.author='Pengguna lokal';box.append(fragment);return box;}
function sameBlock(range){const parent=n=>(n.nodeType===1?n:n.parentElement)?.closest('p,h1,h2,h3,li,td,th');return parent(range.startContainer)===parent(range.endContainer);}
editor.addEventListener('beforeinput',event=>{if(!tracking||readOnly||event.isComposing)return;if(!['insertText','deleteContentBackward','deleteContentForward'].includes(event.inputType))return;const s=getSelection();if(!s.rangeCount||!editor.contains(s.anchorNode))return;const r=s.getRangeAt(0);if(!sameBlock(r))return;const base=s.anchorNode.nodeType===1?s.anchorNode:s.anchorNode.parentElement;if(base?.closest('ins[data-change]')&&r.collapsed)return;if(event.inputType.startsWith('delete')&&r.collapsed){if(r.startContainer.nodeType!==3)return;const node=r.startContainer,pos=r.startOffset;if(event.inputType==='deleteContentBackward'){if(!pos)return;const before=node.data.slice(0,pos);const points=Array.from(before);r.setStart(node,pos-(points.at(-1)?.length||1));}else{if(pos>=node.length)return;r.setEnd(node,pos+(Array.from(node.data.slice(pos))[0]?.length||1));}}event.preventDefault();const id='change-'+uid(),frag=document.createDocumentFragment();if(!r.collapsed){const deleted=r.extractContents();const del=revisionHTML(deleted,'del',id);del.contentEditable='false';frag.append(del);}let anchor;if(event.inputType==='insertText'){const ins=revisionHTML(document.createTextNode(event.data||''),'ins',id);frag.append(ins);anchor=ins;}else{anchor=document.createTextNode('');frag.append(anchor);}r.insertNode(frag);const caret=document.createRange();if(anchor.nodeType===1){caret.selectNodeContents(anchor);caret.collapse(false);}else caret.setStartAfter(anchor);caret.collapse(true);s.removeAllRanges();s.addRange(caret);rememberSelection();changed();});
function toggleTracking(){tracking=!tracking;toast('Lacak perubahan teks '+(tracking?'aktif. Ketikan dan penghapusan teks satu paragraf akan ditandai.':'nonaktif.'));renderRibbon('review');}
function processChanges(accept,onlyId){mutate(()=>{for(const n of [...editor.querySelectorAll('ins[data-change],del[data-change]')]){if(onlyId&&n.dataset.change!==onlyId)continue;const keep=accept?n.tagName==='INS':n.tagName==='DEL';if(keep)n.replaceWith(...n.childNodes);else n.remove();}});}
function revisions(){const items=[...editor.querySelectorAll('ins[data-change],del[data-change]')];showDialog('Perubahan teks',items.length?'<p>Lacak perubahan mencakup ketikan dan penghapusan teks biasa satu paragraf. Format, tabel, gambar, dan tempelan tidak dilacak.</p><div id="revisionList" class="revision-list"></div>':'<p>Belum ada perubahan teks yang ditandai.</p>',null);const list=$('revisionList');if(!list)return;for(const n of items){const item=document.createElement('div');item.className='revision-item';const text=document.createElement('span');text.textContent=(n.tagName==='INS'?'Ditambahkan: ':'Dihapus: ')+n.textContent.slice(0,150);const accept=button('Terima',()=>{$('dialog').close();processChanges(true,n.dataset.change);}),reject=button('Tolak',()=>{$('dialog').close();processChanges(false,n.dataset.change);});accept.className=reject.className='secondary';item.append(text,accept,reject);list.append(item);}}
function compareDialog(){persist();showDialog('Bandingkan teks dokumen','<label>Dokumen pembanding<select name="doc">'+docs.filter(d=>d.id!==current.id).map(d=>'<option value="'+escapeHTML(d.id)+'">'+escapeHTML(d.title)+'</option>').join('')+'</select></label><p>Perbandingan teks per baris, tanpa membandingkan format. Buat atau impor dokumen kedua terlebih dahulu.</p>',d=>{const other=docs.find(x=>x.id===d.get('doc'));if(!other)throw Error('Belum ada dokumen pembanding.');const temp=document.createElement('div');temp.innerHTML=other.html;temp.querySelectorAll('.wc-running').forEach(n=>n.remove());const textOf=root=>[...root.querySelectorAll('p,h1,h2,h3,li,td,th')].filter(el=>!el.querySelector('p,h1,h2,h3,li,td,th')).map(el=>el.textContent).join('\n');const changes=WC.diffLines(textOf(editor),textOf(temp));queueMicrotask(()=>{showDialog('Hasil perbandingan','<p>Merah: hanya di dokumen aktif. Hijau: hanya di pembanding.</p><div style="max-height:420px;overflow:auto">'+changes.map(c=>'<div class="diff-row '+c.type+'">'+(c.type==='insert'?'+ ':c.type==='delete'?'− ':'  ')+escapeHTML(c.text)+'</div>').join('')+'</div>',null);$('dialog').classList.add('wide');});},'Bandingkan');}
function versionDialog(){persist();showDialog('Versi tersimpan','<p>Simpan snapshot manual sebelum perubahan besar. Maksimal 10 versi per dokumen.</p><label>Nama versi<input id="versionName" value="Versi '+new Date().toLocaleString('id-ID')+'"></label><button type="button" class="primary" id="saveVersion">Simpan versi sekarang</button><div id="versionsList" class="revision-list"></div>',null);$('saveVersion').onclick=()=>{current.versions=Array.isArray(current.versions)?current.versions:[];current.versions.unshift({id:uid(),name:$('versionName').value||'Versi',html:cleanHTML(),layout:{...current.layout},appearance:{...current.appearance},date:Date.now()});current.versions=current.versions.slice(0,10);persist();$('dialog').close();toast(storageFailed?'Penyimpanan penuh. Unduh cadangan.':'Snapshot dokumen tersimpan.');};for(const v of current.versions||[]){const item=document.createElement('div');item.className='revision-item';const name=document.createElement('span');name.textContent=v.name;const restore=button('Pulihkan',()=>{$('dialog').close();showDialog('Pulihkan versi?','<p>Isi aktif diganti dengan versi ini. Anda dapat memakai Urungkan untuk mengembalikan isi sebelumnya.</p>',()=>{editor.innerHTML=sanitize(v.html);current.layout=normalizedLayout(v.layout);current.appearance=WC.appearance(v.appearance);applyLayout();applyAppearance();changed();paginate();persist();},'Pulihkan');});restore.className='secondary';item.append(name,restore);$('versionsList').append(item);}}
function toggleReadOnly(){readOnly=!readOnly;editor.contentEditable=String(!readOnly);const label=document.querySelector('.mode-label');label.innerHTML='<span></span> '+(readOnly?'Mode baca':'Mode menyunting');toast(readOnly?'Mode baca aktif.':'Penyuntingan diaktifkan.');renderRibbon('review');}
const previousCommand=command;
