function commandPalette(){showDialog('Cari alat dan perintah','<input id="paletteQuery" aria-label="Cari perintah" placeholder="Contoh: tabel, margin, daftar isi…" autocomplete="off"><div id="paletteList" class="search-commands"></div>',null);const update=()=>{const q=$('paletteQuery').value.toLocaleLowerCase('id');$('paletteList').replaceChildren();for(const item of toolsRegistry.filter(t=>t.label.toLocaleLowerCase('id').includes(q)).slice(0,25)){const b=document.createElement('button');b.type='button';b.innerHTML=wcIcon(item.icon)+'<span>'+escapeHTML(item.label)+'</span><small>'+escapeHTML(item.tab)+'</small>';b.onclick=()=>{$('dialog').close();item.action();};$('paletteList').append(b);}};$('paletteQuery').oninput=update;update();$('paletteQuery').focus();}
function about(){showDialog('Tentang WordCraft','<p><b>WordCraft 2.0</b> — editor dokumen lokal dengan antarmuka ribbon yang terinspirasi Word desktop.</p><p>HTML, CSS, dan JavaScript tanpa layanan cloud atau proses build. Berjalan di GitHub Pages.</p><p>Ini bukan Microsoft Word dan belum memiliki seluruh fitur atau kompatibilitas Microsoft Word. Format DOCX kompleks, kolaborasi realtime, makro, serta pemeriksaan tata bahasa lanjutan belum didukung.</p>',null);}
help=function(){showDialog('Bantuan WordCraft','<p><b>Mulai:</b> ketik di halaman putih. Pilih teks lalu gunakan ribbon Beranda. Klik tabel atau gambar untuk membuka tab kontekstual.</p><p><b>File:</b> dokumen baru, templat, buka berkas, versi, ekspor, cetak/PDF.<br><b>Referensi:</b> daftar isi dari Judul 1–3, catatan akhir, kutipan, daftar pustaka.<br><b>Surat:</b> muat CSV dengan header; sisipkan {{Nama}}; pratinjau; unduh surat gabungan.<br><b>Tinjau:</b> komentar, pelacakan teks dasar, perbandingan teks, versi manual.</p><p><b>Pintasan:</b> Ctrl/⌘+S simpan, B tebal, I miring, U garis bawah, Z urungkan, Y ulangi, F cari, H ganti, P cetak. Alt+Q cari perintah. Esc keluar fokus/baca.</p><p>Penyimpanan menggunakan browser ini. Unduh cadangan .wordcraft untuk menjaga dokumen. Pelacakan perubahan hanya mencakup ketikan dan penghapusan teks satu paragraf; tidak mencakup format, tempelan, tabel, atau gambar. Catatan akhir dan daftar isi tidak memiliki field otomatis Word. Lihat README untuk dukungan lengkap.</p>',null);};
// Keep modal setup isolated; an input callback from Font must not leak to other dialogs.
const previousShowDialog=showDialog;
showDialog=function(...args){$('dialog').classList.remove('wide');$('dialogForm').oninput=null;previousShowDialog(...args);};
$('dialog').addEventListener('close',()=>{$('dialogForm').oninput=null;});
$('quickSave').innerHTML=wcIcon('save');$('quickSave').onclick=()=>{persist();toast(storageFailed?'Penyimpanan penuh. Unduh cadangan.':'Dokumen tersimpan di perangkat.');};$('quickUndo').innerHTML=wcIcon('undo');$('quickUndo').onclick=()=>travelHistory(-1);$('quickRedo').innerHTML=wcIcon('redo');$('quickRedo').onclick=()=>travelHistory(1);$('commandSearch').onclick=commandPalette;$('collapseRibbon').onclick=()=>document.body.classList.toggle('ribbon-collapsed');$('showComments').onclick=comments;$('addComment').onclick=addComment;
const exitReading=document.createElement('button');exitReading.id='exitReading';exitReading.className='exit-reading';exitReading.textContent='Kembali menyunting · Esc';exitReading.hidden=true;exitReading.onclick=()=>{document.body.classList.remove('focus-mode','read-mode');viewMode('print');exitReading.hidden=true;};document.body.append(exitReading);
const modes=document.createElement('span');modes.className='view-buttons';for(const [mode,icon,label] of [['read','book','Mode baca'],['print','page','Tata letak cetak'],['web','web','Tata letak web']]){const b=document.createElement('button');b.dataset.view=mode;b.title=label;b.setAttribute('aria-label',label);b.innerHTML=wcIcon(icon);b.onclick=()=>viewMode(mode);if(mode==='print')b.className='active';modes.append(b);}$('zoomOut').before(modes);
function contextTab(id,label){let b=document.querySelector('[data-tab="'+id+'"]');if(!b){b=document.createElement('button');b.type='button';b.dataset.tab=id;b.className='context-tab';b.setAttribute('role','tab');b.setAttribute('aria-selected','false');b.textContent=label;b.onclick=()=>renderRibbon(id);document.querySelector('.tabs').append(b);}return b;}
editor.addEventListener('click',e=>{if(e.target.closest('.wc-running'))return;const a=e.target.closest('a[href^="#"]');if(a){e.preventDefault();const target=editor.querySelector('[id="'+a.getAttribute('href').slice(1).replace(/["\\]/g,'')+'"]');target?.scrollIntoView({block:'center',behavior:'smooth'});}editor.querySelectorAll('.selected-image').forEach(n=>n.classList.remove('selected-image'));selectedImage=e.target.tagName==='IMG'?e.target:null;const table=e.target.closest('table');const tableTab=contextTab('table','Tata Letak Tabel'),pictureTab=contextTab('picture','Format Gambar');tableTab.hidden=!table;pictureTab.hidden=!selectedImage;if(selectedImage){selectedImage.classList.add('selected-image');renderRibbon('picture');}else if(table&&activeTab!=='table'){renderRibbon('table');}else if(!table&&!selectedImage&&['table','picture'].includes(activeTab)){renderRibbon('home');}updateStats();});
editor.addEventListener('dblclick',e=>{if(e.target.tagName==='IMG'){selectedImage=e.target;imageProperties();}});
editor.addEventListener('keydown',e=>{if(e.key==='Tab'&&e.target.closest('table')){const n=getSelection().anchorNode;const cell=(n?.nodeType===1?n:n?.parentElement)?.closest('td,th');if(cell){const cells=[...cell.closest('table').querySelectorAll('td,th')];const next=cells[cells.indexOf(cell)+(e.shiftKey?-1:1)];if(next){e.preventDefault();const r=document.createRange();r.selectNodeContents(next);r.collapse(true);getSelection().removeAllRanges();getSelection().addRange(r);rememberSelection();}}}});
editor.addEventListener('load',schedulePagination,true);
document.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='q'){e.preventDefault();commandPalette();}if(e.key==='Escape'){if($('backstage'))$('backstage').hidden=true;document.body.classList.remove('focus-mode','read-mode');$('exitReading').hidden=true;if(readOnly&&editor.contentEditable==='false'&&document.querySelector('.mode-label').textContent.includes('menyunting')){readOnly=false;editor.contentEditable='true';}}});
const findOptions=document.createElement('div');findOptions.className='find-options';findOptions.innerHTML='<label><input id="findCase" type="checkbox"> Peka huruf</label><label><input id="findWhole" type="checkbox"> Kata utuh</label>';$('findPanel').append(findOptions);
const oldMatches=matches;
matches=function(){const query=$('findText').value;if(!query)return[];const sensitive=$('findCase').checked,whole=$('findWhole').checked,found=[];const blocks=[...editor.querySelectorAll('p,h1,h2,h3,h4,li,td,th')].filter(el=>!el.closest('.wc-running')&&!el.querySelector('p,h1,h2,h3,h4,li,td,th'));for(const block of blocks){const nodes=[],walker=document.createTreeWalker(block,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('del')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let n,text='';while((n=walker.nextNode())){nodes.push({node:n,start:text.length,end:text.length+n.length});text+=n.data;}const hay=sensitive?text:text.toLocaleLowerCase('id'),needle=sensitive?query:query.toLocaleLowerCase('id');let at=0;while((at=hay.indexOf(needle,at))>=0){const end=at+needle.length,word=c=>c&&/[\p{L}\p{N}_]/u.test(c);if(!whole||(!word(text[at-1])&&!word(text[end]))){const startNode=nodes.find(x=>x.end>at),endNode=nodes.find(x=>x.end>=end);if(startNode&&endNode){const r=document.createRange();r.setStart(startNode.node,at-startNode.start);r.setEnd(endNode.node,end-endNode.start);found.push(r);}}at=end;}}return found;};
replaceAll=function(){const found=matches();if(!found.length){toast('Tidak ditemukan');return;}const value=$('replaceText').value;mutate(()=>{for(const range of found.reverse()){range.deleteContents();range.insertNode(document.createTextNode(value));}});$('findResult').textContent=found.length+' diganti';findCursor=0;findRange=null;};
for(const id of ['findCase','findWhole'])$(id).onchange=()=>{findCursor=0;findRange=null;};
function plainText(root=editor){return[...root.querySelectorAll('p,h1,h2,h3,h4,h5,h6,li,td,th,div')].filter(el=>!el.closest('.wc-running,del')&&!el.querySelector('p,h1,h2,h3,h4,h5,h6,li,td,th,div')).map(el=>el.textContent.replace(/\u200b/g,'')).join('\n');}
statsDialog=function(){const text=plainText(),words=text.trim()?text.trim().split(/\s+/u).length:0;showDialog('Statistik dokumen','<p><b>'+words+'</b> kata<br><b>'+text.length+'</b> karakter dengan spasi<br><b>'+text.replace(/\s/g,'').length+'</b> karakter tanpa spasi<br><b>'+editor.querySelectorAll('.wc-sheet').length+'</b> halaman kanvas<br><b>'+editor.querySelectorAll('img').length+'</b> gambar<br><b>'+editor.querySelectorAll('table').length+'</b> tabel<br><b>'+current.comments.length+'</b> komentar</p><p>Pagination browser dapat berbeda dengan Word dan hasil cetak. Teks revisi yang dihapus tidak dihitung.</p>',null);};
// Register every ribbon command once so command search covers tools outside the active tab.
for(const tab of ['home','insert','draw','design','layout','references','mailings','review','view','help','table','picture'])renderRibbon(tab);
current.appearance=WC.appearance(current.appearance);editor.contentEditable='true';applyAppearance();paginate();renderRibbon('home');renderComments();setZoom(innerWidth<800?65:100);persist();
function exportRoot(){const root=document.createElement('div');root.innerHTML=cleanHTML();const originals=[...editor.querySelectorAll('img')];root.querySelectorAll('img').forEach((img,i)=>{const original=originals[i];if(original){const w=original.getBoundingClientRect().width/(zoom/100)||original.naturalWidth||400;const ratio=(original.naturalHeight||250)/(original.naturalWidth||400);img.width=Math.round(w);img.height=Math.round(w*ratio);}});root.querySelectorAll('del,.wc-running').forEach(n=>n.remove());root.querySelectorAll('ins,mark[data-comment]').forEach(n=>n.replaceWith(...n.childNodes));return root;}
exportDialog=function(){persist();showDialog('Ekspor dokumen','<p>Pilih format unduhan. Cadangan WordCraft mempertahankan komentar, revisi, sumber, dan pengaturan aplikasi.</p><div id="exportChoices"></div><p>DOCX adalah format dasar yang dapat dibuka di Word. Ekspor menampilkan hasil akhir: penambahan revisi diterima dan teks dihapus tidak disertakan.</p>',null);const choices=[['DOCX','Dokumen Word (.docx)','Teks, format dasar, tabel, gambar, header/footer, nomor halaman',async()=>{const bytes=await WordCraftOffice.exportDocx(exportRoot(),{...current.layout,...current.appearance});download(bytes,filename()+'.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');}],['PDF','PDF / Cetak','Pilih Simpan sebagai PDF di dialog cetak browser',printDocument],['HTML','Dokumen HTML','Dokumen yang dapat dibuka di browser',()=>download(exportHTML(),filename()+'.html','text/html;charset=utf-8')],['TXT','Teks biasa','Teks bersih tanpa format dan teks revisi yang dihapus',()=>download(plainText(exportRoot()),filename()+'.txt','text/plain;charset=utf-8')],['WCF','Cadangan WordCraft','Isi, komentar, revisi, tema, versi, sumber dan data CSV',()=>download(JSON.stringify({format:'wordcraft',version:2,document:{...current,html:cleanHTML()}},null,2),filename()+'.wordcraft','application/json')]];for(const [icon,title,detail,fn] of choices){const b=document.createElement('button');b.type='button';b.className='export-choice';b.innerHTML='<div class="format-icon">'+icon+'</div><div><strong>'+title+'</strong><span>'+detail+'</span></div>';b.onclick=async()=>{$('dialog').close();try{await fn();}catch(e){toast('Ekspor gagal: '+e.message);}};$('exportChoices').append(b);}};
$('exportButton').onclick=()=>exportDialog();$('helpButton').onclick=()=>help();$('wordCount').onclick=()=>statsDialog();
// A selection must stay in the sheet when formatting from quick-access controls.
for(const id of ['quickSave','quickUndo','quickRedo'])$(id).onmousedown=e=>e.preventDefault();
// A compact selection toolbar, as in desktop word processors.
const mini=$('selectionContext');
for(const [label,content,fn] of [['Tebal','<b>B</b>',()=>command('bold')],['Miring','<i>I</i>',()=>command('italic')],['Garis bawah','<u>U</u>',()=>command('underline')],['Font',wcIcon('text'),fontDialog],['Komentar',wcIcon('comment'),comments]]){const b=button(label,()=>{mini.hidden=true;fn();},{icon:content});mini.append(b);}
function selectionState(){const selection=getSelection();if(!selection.rangeCount||!editor.contains(selection.anchorNode)){mini.hidden=true;return;}const node=selection.anchorNode.nodeType===1?selection.anchorNode:selection.anchorNode.parentElement;if(node){const computed=getComputedStyle(node),family=computed.fontFamily.split(',')[0].replace(/["']/g,'');const font=$('fontFamilyChooser'),size=$('fontSizeChooser');if(font&&[...font.options].some(o=>o.value===family))font.value=family;if(size){const pt=Math.round(parseFloat(computed.fontSize)*.75*10)/10;size.querySelector('[data-dynamic]')?.remove();if(![...size.options].some(o=>+o.value===pt)){const option=document.createElement('option');option.value=pt;option.textContent=pt;option.dataset.dynamic='true';size.append(option);}size.value=pt;}}if(selection.isCollapsed)mini.hidden=true;updateStats();}
document.addEventListener('selectionchange',selectionState);
editor.addEventListener('mouseup',()=>setTimeout(()=>{const selection=getSelection();if(readOnly||!selection.rangeCount||selection.isCollapsed||!editor.contains(selection.anchorNode)||selectedImage){mini.hidden=true;return;}const rect=selection.getRangeAt(0).getBoundingClientRect();mini.style.left=Math.max(8,Math.min(innerWidth-220,rect.left))+'px';mini.style.top=Math.max(208,rect.top-39)+'px';mini.hidden=false;},0));
$('canvas').addEventListener('scroll',()=>mini.hidden=true);
editor.addEventListener('input',()=>mini.hidden=true);
document.addEventListener('pointerdown',e=>{if(!mini.contains(e.target)&&!editor.contains(e.target))mini.hidden=true;});
